// ── Celda 2: Setup — instalar deps si no están disponibles ───────────────────
// chromadb-default-embed = fork oficial de Chroma de @xenova/transformers.
// Misma API, mismo modelo all-MiniLM-L6-v2 (~30MB descarga en runtime, 1ª vez).
// 100% compatible con los embeddings del ingestor Python.
const { execSync } = require('child_process');
const path = require('path');
const fs = require('fs');

const NNB_DIR = path.join(
  process.env.HOME || process.env.USERPROFILE,
  'OASIS', 'aleph-scriptorium', 'VectorMachineSDK'
);

const chromaInstalled = fs.existsSync(path.join(NNB_DIR, 'node_modules', 'chromadb'));
const embedInstalled  = fs.existsSync(path.join(NNB_DIR, 'node_modules', 'chromadb-default-embed'));

if (!chromaInstalled || !embedInstalled) {
  console.log('📦 Instalando deps (chromadb + chromadb-default-embed)...');
  execSync('npm install', { cwd: NNB_DIR, stdio: 'pipe' });
  console.log('✓ Deps instaladas');
} else {
  console.log('✓ chromadb             :', path.join(NNB_DIR, 'node_modules', 'chromadb'));
  console.log('✓ chromadb-default-embed:', path.join(NNB_DIR, 'node_modules', 'chromadb-default-embed'));
}

// ── Celda 3: Verificar servidor Chroma ────────────────────────────────────────
const STORAGE_PATH = path.join(
  process.env.HOME || process.env.USERPROFILE,
  'OASIS', 'aleph-scriptorium', 'ARCHIVO', 'PLUGINS', 'VECTOR_MACHINE', 'STORAGE'
);

async function isChromaRunning() {
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 1500);
    const r = await fetch('http://localhost:8000/api/v2/heartbeat', { signal: ctrl.signal });
    clearTimeout(t);
    return r.ok;
  } catch { return false; }
}

const running = await isChromaRunning();

if (running) {
  console.log('✓ Chroma server activo en localhost:8000 — listo para ingestar');
} else {
  console.log('⚠ Chroma no responde en localhost:8000');
  console.log('  Tip: ejecuta la tarea VS Code → VMS: Start [Chroma]');
  console.log('  O desde terminal: cd VectorMachineSDK && bash start.sh');
  console.log('  Intentando arrancar con uvx...');

  const { spawn } = require('child_process');
  const srv = spawn(
    'uvx',
    ['--from', 'chromadb', 'chroma', 'run', '--path', STORAGE_PATH, '--host', '0.0.0.0', '--port', '8000'],
    { cwd: NNB_DIR, detached: true, stdio: 'ignore', shell: true }
  );
  srv.unref();

  let ready = false;
  for (let i = 0; i < 30; i++) {
    await new Promise(r => setTimeout(r, 500));
    if (await isChromaRunning()) { ready = true; break; }
  }
  if (ready) {
    console.log('✓ Chroma server listo  (pid', srv.pid, ')');
  } else {
    console.error('✗ Chroma server no respondió — arranca VMS: Start [Chroma] manualmente');
  }
}

console.log('Storage:', STORAGE_PATH);

// ── Celda 4: Conectar ChromaClient y listar colecciones existentes ───────────
const { ChromaClient } = require(path.join(NNB_DIR, 'node_modules', 'chromadb'));

const client = new ChromaClient({
  host: 'localhost',
  port: 8000,
  database: 'default_database',
});

await client.heartbeat();
const existing = await client.listCollections();
const getName = (c) => typeof c === 'string' ? c : c.name;
console.log('✓ Conectado a Chroma HTTP server');
console.log('Colecciones existentes:', existing.map(getName));

// ── Celda 6: chunkMarkdown + embeddings vía chromadb-default-embed + ingestFile
// chromadb-default-embed = fork oficial Chroma de @xenova/transformers.
// Modelo: Xenova/all-MiniLM-L6-v2 (idéntico al DefaultEmbeddingFunction Python).

const COLLECTION_CONFIGURATION = {
  hnsw: {
    space: 'cosine',
  },
};

const SOURCE_ROOT_PATH = path.join(
  process.env.HOME || process.env.USERPROFILE,
  'OASIS', 'aleph-scriptorium', 'DocumentMachineSDK', 'DRAFT2'
);

// Carga el pipeline una sola vez y lo reutiliza entre celdas
const { pipeline, env } = require(path.join(NNB_DIR, 'node_modules', 'chromadb-default-embed'));
env.cacheDir = path.join(NNB_DIR, '.model-cache'); // modelo ONNX en disco local

let _embedder = null;
async function getEmbedder() {
  if (!_embedder) {
    console.log('  Cargando modelo all-MiniLM-L6-v2 (1ª vez: ~30MB descarga)...');
    _embedder = await pipeline('feature-extraction', 'Xenova/all-MiniLM-L6-v2');
    console.log('  ✓ Modelo listo');
  }
  return _embedder;
}

async function generateEmbeddings(texts) {
  const pipe = await getEmbedder();
  const out = await pipe(texts, { pooling: 'mean', normalize: true });
  return out.tolist();
}

function chunkMarkdown(text, maxChars = 700) {
  const parts = text.split(/(?=^#{1,3} .+)/m);
  const raw = [];
  for (const part of parts) {
    const headMatch = part.match(/^(#{1,3} [^\n]+)/);
    const title = headMatch ? headMatch[1].trim() : '';
    const body = headMatch ? part.slice(headMatch[0].length).trim() : part.trim();
    if (body) raw.push({ title, text: body });
  }
  const final = [];
  for (const chunk of raw) {
    if (chunk.text.length <= maxChars) {
      final.push(chunk);
    } else {
      const paras = chunk.text.split(/\n\n+/).filter(p => p.trim());
      let buf = '';
      for (const para of paras) {
        if (buf.length + para.length > maxChars && buf) {
          final.push({ title: chunk.title, text: buf.trim() });
          buf = para;
        } else {
          buf += (buf ? '\n\n' : '') + para;
        }
      }
      if (buf.trim()) final.push({ title: chunk.title, text: buf.trim() });
    }
  }
  return final.filter(c => c.text.length >= 50);
}

async function ingestFile(colName, filePath, bloque, tipo, idPrefix) {
  const col = await client.getOrCreateCollection({
    name: colName,
    embeddingFunction: { generate: async () => [] }, // embeddings explícitos
    configuration: COLLECTION_CONFIGURATION,
  });
  const existing = await col.get({ include: ['metadatas'] });
  const existingIds = new Set(existing.ids);

  const text = fs.readFileSync(filePath, 'utf-8');
  const chunks = chunkMarkdown(text);

  const ids = [], docs = [], metas = [];
  for (let i = 0; i < chunks.length; i++) {
    const chunk = chunks[i];
    const docId = `${idPrefix}-${String(i + 1).padStart(2, '0')}`;
    if (existingIds.has(docId)) continue;
    const label = chunk.title ? chunk.title.slice(0, 40) : docId;
    ids.push(docId);
    docs.push(chunk.text);
    metas.push({ bloque, tipo, marca: label });
  }

  if (ids.length > 0) {
    console.log(`  Generando ${ids.length} embeddings (chromadb-default-embed)...`);
    const embeddings = await generateEmbeddings(docs);
    await col.add({ ids, documents: docs, metadatas: metas, embeddings });
  }

  const total = await col.count();
  console.log(`  ${colName.padEnd(35)} / ${idPrefix}: +${ids.length} chunks  (total ${total})`);
  return ids.length;
}

console.log('✓ Funciones cargadas. SOURCE_ROOT_PATH:', SOURCE_ROOT_PATH);
console.log('  Configuración HNSW nueva:', JSON.stringify(COLLECTION_CONFIGURATION));
console.log('  Archivos disponibles:', fs.readdirSync(SOURCE_ROOT_PATH).join(', '));

// ── Celda final: Verificación ─────────────────────────────────────────────────
const allCols = await client.listCollections();
// listCollections puede devolver string[] o {name:string}[] según versión chromadb
const getName = (c) => typeof c === 'string' ? c : c.name;
const corpusCols = allCols.filter(c => getName(c).startsWith('mc_liria_rojipardismo_'));
const modTotalCols = allCols.filter(c => getName(c).startsWith('mc_'));

console.log('=== mod-cf_ec_transc / LIRIA_ROJIPARDISMO_S01 ===');
let corpusTot = 0;
for (const c of corpusCols.sort((a, b) => getName(a).localeCompare(getName(b)))) {
  const col = await client.getCollection({ name: getName(c) });
  const n = await col.count();
  corpusTot += n;
  console.log(`  ${getName(c).padEnd(35)}  ${String(n).padStart(4)} chunks`);
}
console.log(`  ${'CORPUS TOTAL'.padEnd(35)}  ${String(corpusTot).padStart(4)} chunks`);

console.log('');
console.log('=== mod-cf_ec_transc / ACUMULADO ===');
let globalTot = 0;
for (const c of modTotalCols.sort((a, b) => getName(a).localeCompare(getName(b)))) {
  const col = await client.getCollection({ name: getName(c) });
  const n = await col.count();
  globalTot += n;
  console.log(`  ${getName(c).padEnd(35)}  ${String(n).padStart(4)} chunks`);
}
console.log(`  ${'TOTAL mc_*'.padEnd(35)}  ${String(globalTot).padStart(4)} chunks`);
